/// <summary>
/// Controller class for VFD variance vendor Claim process.
/// </summary>
class METVFDVarVendClaimJournalController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// VFD variance vendor Claim process.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(METVFDVarVendClaimJournalService));
    this.parmMethodName(methodStr(METVFDVarVendClaimJournalService, processOperation));
    this.parmDialogCaption(this.caption());
}

/// <summary>
/// Caption of the batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:VFDVarVendClaimJourProcess";
}

/// <summary>
/// Main method required to run the opration
/// </summary>
/// <param name = "args">Args</param>
public static void main(Args args)
{
    METVFDVarVendClaimJournalController controller;

    controller = new METVFDVarVendClaimJournalController();
    controller.parmArgs(args);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}

/// <summary>
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METVFDVarVendClaimJournalController construct()
{
    return new METVFDVarVendClaimJournalController();
}

/// <summary>
/// Control whether batch task should retry in case of SQL transient errors.
/// </summary>
/// <returns>true if task should be retried; otherwise, false.</returns>
public boolean isRetryable()
{
    return true;
}
